-- The previous release erased a person's questions and digests before the person's turns, in separate commits. An
-- erasure that stopped between them left turns of an account under erasure without the entry that they answer. Erasure
-- deletes these turns anyway; a turn's run goes with it.
DELETE FROM public.conversation_turn t
WHERE EXISTS (SELECT FROM public.account a WHERE a.id = t.account_id AND a.status IN ('DELETING', 'DELETED'))
  AND NOT EXISTS (
      SELECT FROM public.agent_run r
      JOIN public.conversation_entry e
        ON (e.turn_id, e.workspace_id, e.conversation_id) = (t.id, t.workspace_id, t.conversation_id)
       AND ((r.kind = 'TURN' AND e.kind = 'USER') OR (r.kind = 'DIGEST' AND e.kind = 'DIGEST' AND e.surface = 'SYSTEM'))
      WHERE (r.id, r.workspace_id) = (t.run_id, t.workspace_id));

DO $$
DECLARE
 missing bigint;
BEGIN
 SELECT count(*) INTO missing FROM public.agent_run r
 WHERE r.kind IN ('TURN', 'DIGEST') AND NOT EXISTS (
     SELECT FROM public.conversation_turn t
     JOIN public.conversation_entry e
       ON (e.turn_id, e.workspace_id, e.conversation_id) = (t.id, t.workspace_id, t.conversation_id)
      AND ((r.kind = 'TURN' AND e.kind = 'USER') OR (r.kind = 'DIGEST' AND e.kind = 'DIGEST' AND e.surface = 'SYSTEM'))
     WHERE (t.run_id, t.workspace_id) = (r.id, r.workspace_id));
 IF missing > 0 THEN
  RAISE EXCEPTION '% conversation runs have no turn with its question or digest entry, so no owner can be stored', missing
   USING ERRCODE = 'object_not_in_prerequisite_state';
 END IF;
END $$;

ALTER TABLE public.agent_run ADD COLUMN account_id bigint, ADD COLUMN conversation_id uuid, ADD COLUMN subject_seq bigint;

CREATE OR REPLACE FUNCTION public.guard_agent_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id, NEW.workspace_id, NEW.kind, NEW.band, NEW.created_at, NEW.start_within_seconds)
    IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.kind, OLD.band, OLD.created_at, OLD.start_within_seconds) THEN
  RAISE EXCEPTION 'a run''s identity is immutable' USING ERRCODE = '55000';
 END IF;
 IF NEW.concurrency_key IS DISTINCT FROM OLD.concurrency_key AND NOT (OLD.state = 'QUEUED' AND NEW.state = 'QUEUED') THEN
  RAISE EXCEPTION 'only a queued run moves to another subject' USING ERRCODE = '55000';
 END IF;
 -- An ended run changes only when its turn moves to another owner or ledger position: an absorbed account's
 -- conversations move to the account that claimed it (person_row_sweep, ACCOUNT_ABSORB).
 IF OLD.state = 'ENDED'
    AND (ROW(NEW.account_id, NEW.conversation_id, NEW.subject_seq)
           IS NOT DISTINCT FROM ROW(OLD.account_id, OLD.conversation_id, OLD.subject_seq)
         OR (to_jsonb(NEW) - 'account_id' - 'conversation_id' - 'subject_seq')
           IS DISTINCT FROM (to_jsonb(OLD) - 'account_id' - 'conversation_id' - 'subject_seq')) THEN
  RAISE EXCEPTION 'an ended run is final' USING ERRCODE = '55000';
 END IF;
 IF NEW.attempt < OLD.attempt THEN
  RAISE EXCEPTION 'a run''s spent attempts never decrease' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'QUEUED' AND NEW.state = 'LEASED' THEN
  IF NEW.lease_epoch <> OLD.lease_epoch + 1 THEN
   RAISE EXCEPTION 'a claim takes the next epoch' USING ERRCODE = '23514';
  END IF;
 ELSIF NEW.lease_epoch <> OLD.lease_epoch THEN
  RAISE EXCEPTION 'only a claim changes the epoch' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'LEASED' AND NEW.state = 'LEASED' AND NEW.attempt <> OLD.attempt THEN
  RAISE EXCEPTION 'a renewal spends no attempt' USING ERRCODE = '23514';
 END IF;
 IF NEW.deadline IS DISTINCT FROM OLD.deadline
    AND NOT (NEW.deadline IS NULL AND NEW.state = 'QUEUED')
    AND NOT (NEW.deadline IS NOT NULL AND (OLD.deadline IS NULL OR NEW.deadline < OLD.deadline)) THEN
  RAISE EXCEPTION 'a run''s deadline only moves earlier, until a requeue clears it' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;

UPDATE public.agent_run r SET account_id = t.account_id, conversation_id = t.conversation_id, subject_seq = e.seq
FROM public.conversation_turn t
JOIN public.conversation_entry e
  ON (e.turn_id, e.workspace_id, e.conversation_id) = (t.id, t.workspace_id, t.conversation_id)
WHERE (t.run_id, t.workspace_id) = (r.id, r.workspace_id)
  AND ((r.kind = 'TURN' AND e.kind = 'USER') OR (r.kind = 'DIGEST' AND e.kind = 'DIGEST' AND e.surface = 'SYSTEM'));

ALTER TABLE public.agent_run ADD CONSTRAINT ck_agent_run_owner CHECK (
    CASE WHEN kind IN ('TURN', 'DIGEST')
         THEN account_id IS NOT NULL AND conversation_id IS NOT NULL AND subject_seq IS NOT NULL AND subject_seq > 0
         ELSE account_id IS NULL AND conversation_id IS NULL AND subject_seq IS NULL END);
-- Absorption reads a person's runs by their owner.
CREATE INDEX idx_agent_run_account ON public.agent_run (account_id) WHERE account_id IS NOT NULL;
-- A run names the entry at its position. A foreign key check reads past row-level security, so the entry cannot go,
-- or move to another position, conversation or workspace, while the run exists, for every role. The check waits for
-- the commit, because a turn's run is queued before its entry, and absorption moves entries and runs in separate
-- statements. NO ACTION writes nothing: a change that leaves a run without its entry fails the commit.
-- The foreign key needs a key with the workspace. It replaces the key on (conversation_id, seq), which holds the same
-- fact, as a conversation has one workspace. conversation_id stays first, so the reads of one conversation's entries in
-- seq order keep their index.
ALTER TABLE public.conversation_entry DROP CONSTRAINT uk_conversation_entry_conversation_seq;
ALTER TABLE public.conversation_entry ADD CONSTRAINT uk_conversation_entry_position
    UNIQUE (conversation_id, seq, workspace_id);
ALTER TABLE public.agent_run ADD CONSTRAINT sfk_agent_run_stimulus
    FOREIGN KEY (workspace_id, conversation_id, subject_seq)
    REFERENCES public.conversation_entry (workspace_id, conversation_id, seq)
    ON UPDATE NO ACTION ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED;
-- The foreign key's checks and the entry check of enforce_conversation_turn_run find the runs at one position.
CREATE INDEX idx_agent_run_stimulus ON public.agent_run (workspace_id, conversation_id, subject_seq)
    WHERE conversation_id IS NOT NULL;
-- A turn names its run with the run's owner. A foreign key check reads past row-level security, so it holds for
-- every role. It waits for the commit, because an absorbed account's turns and runs move in separate statements.
ALTER TABLE public.agent_run ADD CONSTRAINT uk_agent_run_owner UNIQUE (id, workspace_id, account_id);
ALTER TABLE public.conversation_turn DROP CONSTRAINT sfk_conversation_turn_run;
ALTER TABLE public.conversation_turn ADD CONSTRAINT sfk_conversation_turn_run
    FOREIGN KEY (run_id, workspace_id, account_id) REFERENCES public.agent_run (id, workspace_id, account_id)
    DEFERRABLE INITIALLY DEFERRED;
-- The turn's key on its run takes the owner too, so that one index serves the foreign key. The foreign key makes the
-- owner a function of the run, so the key still keeps one turn per run.
ALTER TABLE public.conversation_turn DROP CONSTRAINT uk_conversation_turn_run;
ALTER TABLE public.conversation_turn ADD CONSTRAINT uk_conversation_turn_run UNIQUE (run_id, workspace_id, account_id);

