CREATE OR REPLACE FUNCTION public.enforce_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 run_workspace_id bigint;
 checked uuid[];
 one_run uuid;
 run record;
 turn record;
BEGIN
 IF TG_TABLE_NAME = 'agent_run' THEN
  run_workspace_id := NEW.workspace_id;
  checked := ARRAY[NEW.id];
 ELSIF TG_TABLE_NAME = 'conversation_turn' THEN
  run_workspace_id := NEW.workspace_id;
  checked := ARRAY[NEW.run_id];
  IF TG_OP = 'UPDATE' AND OLD.run_id IS DISTINCT FROM NEW.run_id THEN
   checked := checked || OLD.run_id;
  END IF;
 ELSE
  -- A question or digest entry changed or went. The runs that answer it store its position, and the run table has no
  -- row-level security, so the check finds them also when the transaction cannot see their turn. idx_agent_run_stimulus
  -- finds them by the exact position, so the work does not grow with the person's other runs or threads.
  run_workspace_id := OLD.workspace_id;
  SELECT array_agg(r.id) INTO checked FROM public.agent_run r
   WHERE (r.workspace_id, r.conversation_id, r.subject_seq) = (OLD.workspace_id, OLD.conversation_id, OLD.seq);
 END IF;
 FOREACH one_run IN ARRAY COALESCE(checked, '{}') LOOP
  SELECT r.id, r.kind, r.state, r.concurrency_key, r.conversation_id, r.subject_seq INTO run FROM public.agent_run r
   WHERE (r.id, r.workspace_id) = (one_run, run_workspace_id);
  -- A turn's run goes with its turn.
  CONTINUE WHEN NOT FOUND;
  SELECT t.id, t.status, t.surface, t.conversation_id INTO turn FROM public.conversation_turn t
   WHERE (t.run_id, t.workspace_id) = (run.id, run_workspace_id);
  IF NOT FOUND THEN
   CONTINUE WHEN run.kind NOT IN ('TURN', 'DIGEST');
   -- A transaction that has not bound the run's owner sees no turn under row-level security. It fails here, so that
   -- no conversation run commits unchecked.
   RAISE EXCEPTION 'conversation run % has no turn that this transaction can see', run.id USING ERRCODE = '23514';
  END IF;
  IF NOT ((run.kind = 'TURN' AND turn.surface IN ('APP', 'SLACK')) OR (run.kind = 'DIGEST' AND turn.surface = 'SYSTEM')) THEN
   RAISE EXCEPTION 'a conversation turn needs its conversation run kind' USING ERRCODE = '23514';
  END IF;
  IF turn.status IN ('QUEUED', 'RUNNING') AND run.concurrency_key <> 'conversation:' || turn.conversation_id THEN
   RAISE EXCEPTION 'a queued or running turn must use its conversation subject' USING ERRCODE = '23514';
  END IF;
  IF NOT ((turn.status = 'QUEUED' AND run.state = 'QUEUED')
       OR (turn.status = 'RUNNING' AND run.state = 'LEASED')
       OR (turn.status = 'STOPPED' AND run.state IN ('LEASED', 'ENDED'))
       OR (turn.status IN ('DONE', 'FAILED') AND run.state = 'ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', turn.status, run.state
    USING ERRCODE = '23514';
  END IF;
  IF run.conversation_id IS DISTINCT FROM turn.conversation_id THEN
   RAISE EXCEPTION 'a conversation run answers an entry of its turn''s conversation' USING ERRCODE = '23514';
  END IF;
  -- An entry and its turn store the account of their conversation, so an owner policy shows both or neither.
  PERFORM FROM public.conversation_entry e
   WHERE (e.workspace_id, e.conversation_id, e.seq) = (run_workspace_id, run.conversation_id, run.subject_seq)
     AND e.turn_id = turn.id
     AND ((run.kind = 'TURN' AND e.kind = 'USER') OR (run.kind = 'DIGEST' AND e.kind = 'DIGEST' AND e.surface = 'SYSTEM'));
  IF NOT FOUND THEN
   RAISE EXCEPTION 'the entry at a conversation run''s position is the question or digest of its turn'
    USING ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;
DROP TRIGGER conversation_turn_run_agrees ON public.conversation_turn;
CREATE CONSTRAINT TRIGGER conversation_turn_run_agrees
 AFTER INSERT OR UPDATE OF status, run_id, surface, conversation_id ON public.conversation_turn
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.enforce_conversation_turn_run();
DROP TRIGGER agent_run_turn_agrees ON public.agent_run;
CREATE CONSTRAINT TRIGGER agent_run_turn_agrees
 AFTER INSERT OR UPDATE OF state, conversation_id, subject_seq ON public.agent_run
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.kind IN ('TURN', 'DIGEST'))
 EXECUTE FUNCTION public.enforce_conversation_turn_run();
DROP TRIGGER IF EXISTS conversation_entry_run_agrees ON public.conversation_entry;
CREATE CONSTRAINT TRIGGER conversation_entry_run_agrees
 AFTER DELETE OR UPDATE OF seq, kind, surface, turn_id, conversation_id ON public.conversation_entry
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (OLD.turn_id IS NOT NULL AND OLD.kind IN ('USER', 'DIGEST'))
 EXECUTE FUNCTION public.enforce_conversation_turn_run();

