DROP TRIGGER conversation_entry_run_agrees ON public.conversation_entry;
CREATE OR REPLACE FUNCTION public.enforce_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 paired record;
BEGIN
 FOR paired IN
  SELECT t.status, t.surface, t.id, r.state, r.kind, t.workspace_id, t.conversation_id, r.concurrency_key
   FROM public.conversation_turn t JOIN public.agent_run r ON (r.id,r.workspace_id)=(t.run_id,t.workspace_id)
   WHERE (TG_TABLE_NAME='conversation_turn' AND t.id=NEW.id)
      OR (TG_TABLE_NAME='agent_run' AND t.run_id=NEW.id)
 LOOP
  IF NOT ((paired.kind='TURN' AND paired.surface IN ('APP','SLACK'))
       OR (paired.kind='DIGEST' AND paired.surface='SYSTEM'))
     THEN
   RAISE EXCEPTION 'a conversation turn needs its conversation run kind' USING ERRCODE='23514';
  END IF;
  IF paired.status IN ('QUEUED','RUNNING') AND paired.concurrency_key <> 'conversation:' || paired.conversation_id THEN
   RAISE EXCEPTION 'a queued or running turn must use its conversation subject' USING ERRCODE='23514';
  END IF;
  IF paired.kind='DIGEST' AND NOT EXISTS(SELECT 1 FROM public.conversation_entry e
      WHERE (e.turn_id,e.workspace_id)=(paired.id,paired.workspace_id) AND e.kind='DIGEST' AND e.surface='SYSTEM') THEN
   RAISE EXCEPTION 'a digest run needs its real system digest stimulus' USING ERRCODE='23514';
  END IF;
  IF NOT ((paired.status='QUEUED' AND paired.state='QUEUED')
       OR (paired.status='RUNNING' AND paired.state='LEASED')
       OR (paired.status='STOPPED' AND paired.state IN ('LEASED','ENDED'))
       OR (paired.status IN ('DONE','FAILED') AND paired.state='ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', paired.status, paired.state USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;
DROP TRIGGER conversation_turn_run_agrees ON public.conversation_turn;
CREATE CONSTRAINT TRIGGER conversation_turn_run_agrees AFTER INSERT OR UPDATE OF status, run_id, surface ON public.conversation_turn
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.enforce_conversation_turn_run();
DROP TRIGGER agent_run_turn_agrees ON public.agent_run;
CREATE CONSTRAINT TRIGGER agent_run_turn_agrees AFTER UPDATE OF state ON public.agent_run
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.kind IN ('TURN','DIGEST'))
 EXECUTE FUNCTION public.enforce_conversation_turn_run();

changeSet.sql:
CREATE OR REPLACE FUNCTION public.person_row_sweep(rule text, subject_id bigint, other_id bigint, cutoff timestamp with time zone)
    RETURNS integer
    LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
    AS $$
DECLARE
    changed integer := 0;
    counted integer;
    clash record;
    absorbed record;
    admitted boolean;
BEGIN
    IF rule IN ('WORKSPACE_PURGE', 'ACCOUNT_ABSORB') THEN
        -- Hash the supplied and expected MACs before comparing their bytes.
        SELECT EXISTS (
            SELECT FROM lifecycle_private.sweep_key k
            WHERE sha256(convert_to(encode(sha256(k.outer_pad || sha256(k.inner_pad || convert_to(
                concat_ws(':', 'person_row_sweep', rule, subject_id, COALESCE(other_id::text, '-'),
                          pg_current_xact_id(), pg_backend_pid(), extract(epoch FROM transaction_timestamp())),
                'UTF8'))), 'hex'), 'UTF8'))
                = sha256(convert_to(current_setting('hephaestus.sweep_admission', true), 'UTF8'))
        ) INTO admitted;
    END IF;
    IF rule = 'WORKSPACE_PURGE' THEN
        -- subject_id is the purged workspace. A soft purge keeps the workspace row, so no cascade fires.
        IF subject_id IS NULL THEN
            RAISE EXCEPTION 'person_row_sweep: WORKSPACE_PURGE needs the workspace' USING ERRCODE = 'invalid_parameter_value';
        END IF;
        IF NOT admitted THEN
            RAISE EXCEPTION 'person_row_sweep: lifecycle admission required'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
        PERFORM FROM public.workspace w
        WHERE w.id = subject_id AND w.kind = 'TEAM' AND w.status IN ('ACTIVE', 'SUSPENDED')
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'person_row_sweep: workspace is unavailable for purge'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
        DELETE FROM public.conversation_entry WHERE workspace_id = subject_id;
        GET DIAGNOSTICS counted = ROW_COUNT;
        changed := changed + counted;
        DELETE FROM public.conversation_turn WHERE workspace_id = subject_id;
        GET DIAGNOSTICS counted = ROW_COUNT;
        changed := changed + counted;
        DELETE FROM public.conversation WHERE workspace_id = subject_id;
        GET DIAGNOSTICS counted = ROW_COUNT;
        changed := changed + counted;
    ELSIF rule = 'EXPIRED_EXPORTS' THEN
        -- cutoff is now: a ready export past its expiry loses its payload. A cutoff in the future counts as now.
        IF cutoff IS NULL THEN
            RAISE EXCEPTION 'person_row_sweep: EXPIRED_EXPORTS needs the cutoff' USING ERRCODE = 'invalid_parameter_value';
        END IF;
        -- Account erasure locks the account before its exports. Skip a busy account until the next pass.
        WITH eligible AS MATERIALIZED (
            SELECT a.id FROM public.account a
            WHERE a.status IN ('UNCLAIMED', 'ACTIVE', 'BLOCKED')
              AND EXISTS (SELECT FROM public.account_export x WHERE x.account_id = a.id
                          AND x.status = 'READY' AND x.expires_at < LEAST(cutoff, statement_timestamp()))
            ORDER BY a.id
            FOR SHARE OF a SKIP LOCKED
        )
        UPDATE public.account_export x SET status = 'EXPIRED', payload = NULL
        FROM eligible
        WHERE x.account_id = eligible.id AND x.status = 'READY'
          AND x.expires_at < LEAST(cutoff, statement_timestamp());
        GET DIAGNOSTICS changed = ROW_COUNT;
    ELSIF rule = 'ACCOUNT_ABSORB' THEN
        -- subject_id is the absorbed account and other_id the account that claimed it. Where both have a main
        -- conversation in a workspace, the absorbed main's entries follow the claiming main's entries, its turns and
        -- threads move, and it is deleted. Every other conversation of the absorbed account changes owner.
        IF subject_id IS NULL OR other_id IS NULL OR subject_id = other_id THEN
            RAISE EXCEPTION 'person_row_sweep: ACCOUNT_ABSORB needs two different accounts'
                USING ERRCODE = 'invalid_parameter_value';
        END IF;
        IF NOT admitted THEN
            RAISE EXCEPTION 'person_row_sweep: lifecycle admission required'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
        -- Only an unclaimed account is absorbed, by an account that its verified owner signs in to. Both rows are locked
        -- in id order, as the account service locks them, so a concurrent claim cannot change either status.
        PERFORM FROM public.account a WHERE a.id IN (subject_id, other_id) ORDER BY a.id FOR UPDATE;
        IF NOT EXISTS (SELECT FROM public.account a WHERE a.id = subject_id AND a.status = 'UNCLAIMED')
           OR NOT EXISTS (SELECT FROM public.account a WHERE a.id = other_id AND a.status IN ('ACTIVE', 'BLOCKED')) THEN
            RAISE EXCEPTION 'person_row_sweep: only an unclaimed account is absorbed, by an active or blocked account'
                USING ERRCODE = 'object_not_in_prerequisite_state';
        END IF;
        FOR clash IN
            SELECT a.workspace_id, a.id AS absorbed_id, k.id AS kept_id FROM public.conversation a
            JOIN public.conversation k ON k.workspace_id = a.workspace_id
                AND k.account_id = other_id AND k.parent_conversation_id IS NULL
            WHERE a.account_id = subject_id AND a.parent_conversation_id IS NULL
            ORDER BY a.id
            FOR UPDATE OF a, k
        LOOP
            -- The caller prepares each clash first: it returns a running turn of the absorbed main to the queue, moves
            -- the absorbed main's queued runs to the claiming main, and erases the absorbed main's summaries, which
            -- summarize a conversation that no longer exists alone.
            IF EXISTS (SELECT FROM public.conversation_turn t
                       WHERE t.conversation_id = clash.absorbed_id AND t.status = 'RUNNING')
               OR EXISTS (SELECT FROM public.agent_run r
                          WHERE r.workspace_id = clash.workspace_id AND r.state = 'QUEUED'
                            AND r.concurrency_key = 'conversation:' || clash.absorbed_id)
               OR EXISTS (SELECT FROM public.conversation_entry e
                          WHERE e.conversation_id = clash.absorbed_id AND e.kind = 'SUMMARY' AND e.redacted_at IS NULL) THEN
                RAISE EXCEPTION 'person_row_sweep: the absorbed conversation % is not prepared', clash.absorbed_id
                    USING ERRCODE = 'object_not_in_prerequisite_state';
            END IF;
            UPDATE public.conversation_entry e SET conversation_id = clash.kept_id, account_id = other_id,
                seq = top.seq + moved.position
            FROM (SELECT x.id, row_number() OVER (ORDER BY x.seq) AS position
                  FROM public.conversation_entry x WHERE x.conversation_id = clash.absorbed_id) moved,
                 (SELECT COALESCE(max(y.seq), 0) AS seq FROM public.conversation_entry y
                  WHERE y.conversation_id = clash.kept_id) top
            WHERE e.id = moved.id;
            GET DIAGNOSTICS counted = ROW_COUNT;
            changed := changed + counted;
            -- A turn's run stores the position of the turn's question or digest entry, which the merge moved to the
            -- kept conversation. sfk_agent_run_stimulus checks at the commit that each run names its moved entry.
            UPDATE public.agent_run r SET conversation_id = clash.kept_id, subject_seq = e.seq
            FROM public.conversation_turn t
            JOIN public.conversation_entry e ON (e.turn_id, e.workspace_id) = (t.id, t.workspace_id)
                AND e.kind IN ('USER', 'DIGEST')
            WHERE t.conversation_id = clash.absorbed_id AND (r.id, r.workspace_id) = (t.run_id, t.workspace_id);
            GET DIAGNOSTICS counted = ROW_COUNT;
            changed := changed + counted;
            UPDATE public.conversation_turn SET conversation_id = clash.kept_id, account_id = other_id
            WHERE conversation_id = clash.absorbed_id;
            GET DIAGNOSTICS counted = ROW_COUNT;
            changed := changed + counted;
            UPDATE public.conversation SET parent_conversation_id = clash.kept_id
            WHERE parent_conversation_id = clash.absorbed_id;
            GET DIAGNOSTICS counted = ROW_COUNT;
            changed := changed + counted;
            SELECT c.slack_team_id, c.slack_user_id, c.slack_channel_id, c.last_activity_at, c.last_read_at
            INTO absorbed FROM public.conversation c WHERE c.id = clash.absorbed_id;
            DELETE FROM public.conversation WHERE id = clash.absorbed_id;
            -- The Slack identity moves with the merge when the claiming main has none, so the DM keeps its conversation.
            UPDATE public.conversation SET
                slack_user_id = CASE WHEN slack_team_id IS NULL THEN absorbed.slack_user_id ELSE slack_user_id END,
                slack_channel_id = CASE WHEN slack_team_id IS NULL THEN absorbed.slack_channel_id ELSE slack_channel_id END,
                slack_team_id = COALESCE(slack_team_id, absorbed.slack_team_id),
                last_activity_at = GREATEST(last_activity_at, absorbed.last_activity_at),
                last_read_at = GREATEST(last_read_at, absorbed.last_read_at)
            WHERE id = clash.kept_id;
        END LOOP;
        UPDATE public.conversation SET account_id = other_id WHERE account_id = subject_id;
        GET DIAGNOSTICS counted = ROW_COUNT;
        changed := changed + counted;
        -- A conversation run stores the owner of its turn, so the run of every moved turn takes the claiming account.
        UPDATE public.agent_run SET account_id = other_id WHERE account_id = subject_id;
        GET DIAGNOSTICS counted = ROW_COUNT;
        changed := changed + counted;
    ELSE
        RAISE EXCEPTION 'person_row_sweep: unknown rule %', rule USING ERRCODE = 'invalid_parameter_value';
    END IF;
    RETURN changed;
END
$$;
